#!/usr/bin/env node
/**
 * Exports the free grammar question bank and the legal pages as assets for
 * the native Android app (`src/app/android`).
 *
 * Questions are parsed with the same `parseQuestionFile` the website uses,
 * and every derived display value the web widgets compute at runtime
 * (stripped prompts, gap cues, dropbox chunks/commas/punctuation, …) is
 * precomputed here, so the Kotlin app renders and scores without porting
 * the parsing heuristics.
 *
 * Output (git-ignored, regenerated by the Android Gradle build), under
 * src/app/android/app/src/main/assets/:
 *   questions/{A1,A2,B1,B2}.json   grammar bank
 *   vocab/{A1,A2,B1,B2}.json       Wortschatz bank
 *   topics.json                    topic folder → name + question count
 *   hub.json                       Premium hub: topics and vocab sets per level
 *   grammarHints.json              Grammatik-Tipp texts (DE/RU/EN) per topic
 *   dictionary.json                prompt word → lemma, POS, gender, RU/EN gloss
 *   config.json                    backend URL (`SCRIPT_URL` from src/site/data/payment.js)
 *   legal/{agb,datenschutz,impressum}.html
 */

import { register } from 'node:module';
import { mkdirSync, readdirSync, readFileSync, statSync, writeFileSync } from 'node:fs';
import { dirname, join, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

import {
  normalizeGapAnswer,
  parseQuestionFile,
  stripTrailingPromptHint,
} from '../src/site/utils/markdownQuestion.js';
import { resolveInputTextGapCue } from '../src/site/utils/inputTextGapCue.js';
import { resolveDropboxCommas } from '../src/site/utils/dropboxCommas.js';
import { chunkifyDropboxWords } from '../src/site/utils/dropboxChunks.js';
import { extractFixedPunctuation, punctAfterIndex } from '../src/site/utils/dropboxPunctuation.js';
import { PREMIUM_TOPICS } from '../src/site/data/premiumTopics.js';
import { VOCAB_SETS } from '../src/site/data/vocabularySets.js';
import { GRAMMAR_HINTS } from '../src/site/data/grammarHints.js';
import { SCRIPT_URL } from '../src/site/data/payment.js';

// dictionary.js uses Vite's `@/` alias and bare JSON imports.
register('./lib/site-alias-hooks.mjs', import.meta.url);
const { lookupWord, shouldSkipDictionaryWord } = await import('../src/site/utils/dictionary.js');

const __dirname = dirname(fileURLToPath(import.meta.url));
const REPO = resolve(__dirname, '..');
const QUESTIONS_ROOT = join(REPO, 'src', 'site', 'questions');
const VOCAB_ROOT = join(REPO, 'src', 'site', 'questions-vocab');
const EXTRA_MD = join(REPO, 'docs', 'extra.md');
const OUT_DIR = resolve(
  process.argv[2] || join(REPO, 'src', 'app', 'android', 'app', 'src', 'main', 'assets'),
);

const LEVELS = ['A1', 'A2', 'B1', 'B2'];

/** @param {string} dir @return {string[]} */
function walk(dir) {
  /** @type {string[]} */
  const out = [];
  for (const entry of readdirSync(dir).sort()) {
    if (entry.startsWith('_')) continue;
    const full = join(dir, entry);
    if (statSync(full).isDirectory()) out.push(...walk(full));
    else if (entry.endsWith('.md')) out.push(full);
  }
  return out;
}

/** @param {string} text @return {string} */
function normPrompt(text) {
  return stripTrailingPromptHint(text).replace(/\s+/g, ' ').trim().toLowerCase();
}

/** @param {unknown} value @return {string} */
function normToken(value) {
  return String(value || '').trim().toLowerCase();
}

/**
 * Same content fingerprint as `questionContentFingerprint`
 * (`src/site/utils/dedupeQuestions.js`), so the app de-duplicates identically.
 */
function fingerprint(q) {
  switch (q.type) {
    case 'select-one':
      return [q.type, normPrompt(q.prompt), normToken(q.correct)].join('\x00');
    case 'multi-select': {
      const correct = (Array.isArray(q.correct) ? q.correct : [q.correct]).map(normToken).sort();
      return [q.type, normPrompt(q.prompt), correct.join('\x00')].join('\x00');
    }
    case 'dropbox':
      return [q.type, (q.words || []).join('\x00'), (q.commas || []).join(','), (q.codes || []).join(',')].join('\x00');
    case 'input-text': {
      const correct = [...(q.correct || [])].map((c) => normalizeGapAnswer(c)).sort();
      return [q.type, normPrompt(q.prompt), correct.join('\x00')].join('\x00');
    }
    case 'text-gaps':
      return [q.type, normPrompt(q.prompt), (q.gaps || []).map((g) => normToken(g.correct)).join('\x00')].join('\x00');
    default:
      return `${q.type}\x00${q.id}`;
  }
}

/** Mirrors `FillBlank.vue` prompt splitting. */
function exportInputText(q) {
  const lines = stripTrailingPromptHint(q.prompt || '')
    .split('\n')
    .map((l) => l.trim())
    .filter(Boolean);
  const sentence = lines.find((l) => l.includes('___')) || lines[lines.length - 1] || '';
  const instruction = lines.filter((l) => l !== sentence).join(' ');
  const [left = '', right = ''] = sentence.split('___');
  const verbInfinitive = String(q.verbInfinitive || '').trim();
  const wordChoices = Array.isArray(q.wordChoices) ? q.wordChoices.map(String) : [];
  const gapCue = verbInfinitive || wordChoices.length >= 2 ? '' : resolveInputTextGapCue(q);
  return {
    instruction,
    left,
    right,
    correct: (q.correct || []).map(String),
    acceptable: (q.correct || []).map((s) => normalizeGapAnswer(s)),
    hint: q.hint || '',
    verbInfinitive,
    wordChoices: wordChoices.length >= 2 ? wordChoices : [],
    gapCue,
  };
}

/** Groups consecutive TeKaMoLo codes, like `renderTekamoloBreakdown` in `DragDrop.vue`. */
function tekamoloGroups(words, codes) {
  const groups = [];
  for (let i = 0; i < words.length; ) {
    const code = codes[i] || '_';
    const group = { code, text: words[i] };
    while (i + 1 < words.length && (codes[i + 1] || '_') === code) {
      i += 1;
      group.text += ` ${words[i]}`;
    }
    groups.push(group);
    i += 1;
  }
  return groups;
}

/** Mirrors the setup in `DragDrop.vue`. */
function exportDropbox(q) {
  const reference = q.words || [];
  const { coreWords, punctAfter } = extractFixedPunctuation(reference);
  const validOrders = [reference, ...(q.alternatives || [])].map(
    (order) => extractFixedPunctuation(order).coreWords,
  );
  const commaAfter = resolveDropboxCommas({
    words: coreWords,
    commas: q.commas,
    hint: q.hint || stripTrailingPromptHint(q.prompt || ''),
  });
  const chunks = chunkifyDropboxWords(coreWords, { commas: commaAfter }).map((c) => ({
    id: c.id,
    start: c.start,
    words: c.words,
  }));

  let solution = '';
  for (let i = 0; i < coreWords.length; i += 1) {
    if (i > 0) solution += ' ';
    solution += coreWords[i];
    if (commaAfter.includes(i)) solution += ',';
    solution += punctAfterIndex(i, punctAfter);
  }

  const codes = q.codes || [];
  let tekamolo = [];
  if (codes.length && codes.length === reference.length) tekamolo = tekamoloGroups(reference, codes);
  else if (codes.length && codes.length === coreWords.length) tekamolo = tekamoloGroups(coreWords, codes);

  return {
    prompt: stripTrailingPromptHint(q.prompt || ''),
    punctAfter,
    commaAfter,
    chunks,
    validOrders,
    solution,
    tekamolo,
  };
}

/** Mirrors `TextGaps.vue` segment building. */
function exportTextGaps(q) {
  return {
    label: q.hint || '',
    parts: stripTrailingPromptHint(q.prompt || '').split('___'),
    gaps: (q.gaps || []).map((g) => ({ correct: String(g.correct), options: g.options.map(String) })),
  };
}

/** @param {string} html @return {string} */
function stripTags(html) {
  return String(html)
    .replace(/<br\s*\/?>/gi, '\n')
    .replace(/<[^>]+>/g, '')
    .replace(/&nbsp;/g, ' ')
    .replace(/&amp;/g, '&');
}

function exportQuestion(q) {
  const base = { id: q.id, type: q.type, level: q.level, topic: q.topic, fp: fingerprint(q) };
  switch (q.type) {
    case 'select-one':
      return { ...base, prompt: stripTrailingPromptHint(q.prompt || ''), options: q.options, correct: String(q.correct) };
    case 'multi-select': {
      // The web renders this prompt as HTML (`MultiSelect.vue`); the app shows plain text.
      const correct = Array.isArray(q.correct) ? q.correct : [q.correct];
      return { ...base, prompt: stripTags(stripTrailingPromptHint(q.prompt || '')), options: q.options, correctSet: correct.map(String) };
    }
    case 'input-text':
      return { ...base, ...exportInputText(q) };
    case 'dropbox':
      return { ...base, ...exportDropbox(q) };
    case 'text-gaps':
      return { ...base, ...exportTextGaps(q) };
    default:
      return null; // `free-write` has no widget on the web either.
  }
}

/** @param {string} key @return {string} */
function normalizeTopicKey(key) {
  return String(key || '').toUpperCase().replace(/(A1|A2|B1|B2)$/, '');
}

/**
 * Parses and exports one bank (`questions` or `questions-vocab`) per level.
 *
 * @return {Record<string, Record<string, number>>} level → folder → question count
 */
function exportBank(root, outName) {
  mkdirSync(join(OUT_DIR, outName), { recursive: true });
  const counts = {};
  for (const level of LEVELS) {
    const out = [];
    counts[level] = {};
    for (const file of walk(join(root, level))) {
      const topic = file.split(/[/\\]/).at(-2).toUpperCase();
      let parsed;
      try {
        parsed = parseQuestionFile(readFileSync(file, 'utf8'), { level, topic, path: file });
      } catch (err) {
        console.warn(`skip ${file}: ${err.message}`);
        continue;
      }
      const q = exportQuestion(parsed);
      if (!q) continue;
      out.push(q);
      counts[level][topic] = (counts[level][topic] || 0) + 1;
      collectWords(q);
    }
    writeFileSync(join(OUT_DIR, outName, `${level}.json`), JSON.stringify(out));
    console.log(`${outName}/${level}: ${out.length} questions`);
  }
  return counts;
}

function exportCatalogue(grammarCounts, vocabCounts) {
  const topics = {};
  const hub = {};
  for (const level of LEVELS) {
    const names = new Map((PREMIUM_TOPICS[level] || []).map((t) => [t.key.toUpperCase(), t.name]));
    topics[level] = Object.fromEntries(
      Object.entries(grammarCounts[level]).map(([key, count]) => [key, { name: names.get(key) || key, count }]),
    );
    // Same matching as getTopicQuestionCount: compare keys without the CEFR suffix.
    const countFor = (key) => Object.entries(grammarCounts[level])
      .filter(([folder]) => normalizeTopicKey(folder) === normalizeTopicKey(key))
      .reduce((sum, [, n]) => sum + n, 0);
    hub[level] = {
      topics: (PREMIUM_TOPICS[level] || []).map((t) => ({
        key: t.key.toUpperCase(), name: t.name, desc: t.desc, count: countFor(t.key),
      })),
      vocab: (VOCAB_SETS[level] || []).map((v) => ({
        key: v.key.toUpperCase(),
        name: v.name,
        desc: v.desc,
        count: vocabCounts[level][v.key.toUpperCase()] || 0,
        accent: v.theme?.accent || '',
      })),
    };
  }
  writeFileSync(join(OUT_DIR, 'topics.json'), JSON.stringify(topics));
  writeFileSync(join(OUT_DIR, 'hub.json'), JSON.stringify(hub));
  writeFileSync(join(OUT_DIR, 'grammarHints.json'), JSON.stringify(GRAMMAR_HINTS));
}

/** Every word the trainer can show in a prompt (same token rule as `wrapWordsForDictionary`). */
const dictionaryWords = new Set();
const WORD_RE = /[А-Яа-яA-Za-zÄÖÜäöüß]+/g;

function collectWords(q) {
  const texts = [q.prompt, q.left, q.right, q.instruction].filter(Boolean);
  for (const text of texts) {
    for (const word of text.match(WORD_RE) || []) {
      if (!shouldSkipDictionaryWord(word)) dictionaryWords.add(word.toLowerCase());
    }
  }
}

/** Precomputes `lookupWord` (src/site/utils/dictionary.js) for both target languages. */
async function exportDictionary() {
  const out = {};
  for (const word of [...dictionaryWords].sort()) {
    const ru = await lookupWord(word, 'ru');
    const en = await lookupWord(word, 'en');
    const entry = { l: ru.lemma };
    if (ru.pos) entry.p = ru.pos;
    if (ru.gender) entry.g = ru.gender;
    if (ru.source !== 'none') entry.ru = ru.translation;
    if (en.source !== 'none') entry.en = en.translation;
    if (entry.ru || entry.en) out[word] = entry;
  }
  writeFileSync(join(OUT_DIR, 'dictionary.json'), JSON.stringify(out));
  console.log(`dictionary: ${Object.keys(out).length} of ${dictionaryWords.size} words`);
}

/** Same section split and unescape as `src/site/data/legalContent.js`. */
function exportLegal() {
  const raw = readFileSync(EXTRA_MD, 'utf8');
  const sections = [
    { slug: 'datenschutz', marker: '**Datenschutz**' },
    { slug: 'agb', marker: '**AGB**' },
    { slug: 'impressum', marker: '**Impressum**' },
  ];
  mkdirSync(join(OUT_DIR, 'legal'), { recursive: true });
  sections.forEach(({ slug, marker }, i) => {
    const start = raw.indexOf(marker);
    if (start === -1) return;
    const contentStart = start + marker.length;
    const end = i + 1 < sections.length ? raw.indexOf(sections[i + 1].marker, contentStart) : raw.length;
    const chunk = raw.slice(contentStart, end === -1 ? raw.length : end).trim();
    const html = chunk.replace(/\\</g, '<').replace(/\\>/g, '>').replace(/\\#/g, '#');
    writeFileSync(join(OUT_DIR, 'legal', `${slug}.html`), html);
  });
  console.log('legal: agb, datenschutz, impressum');
}

const grammarCounts = exportBank(QUESTIONS_ROOT, 'questions');
const vocabCounts = exportBank(VOCAB_ROOT, 'vocab');
exportCatalogue(grammarCounts, vocabCounts);
await exportDictionary();
writeFileSync(join(OUT_DIR, 'config.json'), JSON.stringify({ scriptUrl: SCRIPT_URL }));
exportLegal();
